 "content": "from collections import Counter


def transform(grid):
    h, w = len(grid), len(grid[0])
    divider_rows = [r for r, row in enumerate(grid) if len(set(row)) == 1]
    divider_cols = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1]
    if not divider_rows or not divider_cols:
        raise ValueError("Expected full-width and full-height divider lines")
    divider_colors = {grid[r][0] for r in divider_rows} | {grid[0][c] for c in divider_cols}
    row_spans = []
    start = 0
    for r in divider_rows:
        if start < r:
            row_spans.append((start, r))
        start = r + 1
    if start < h:
        row_spans.append((start, h))
    col_spans = []
    start = 0
    for c in divider_cols:
        if start < c:
            col_spans.append((start, c))
        start = c + 1
    if start < w:
        col_spans.append((start, w))
    counts = Counter(grid[r][c] for r in range(h) for c in range(w)
                     if r not in divider_rows and c not in divider_cols
                     and grid[r][c] not in divider_colors)
    background = counts.most_common(1)[0][0]
    out = []
    for r0, r1 in row_spans:
        row = []
        for c0, c1 in col_spans:
            marks = sum(grid[r][c] != background and grid[r][c] not in divider_colors
                        for r in range(r0, r1) for c in range(c0, c1))
            row.append(1 if marks > 1 else background)
        out.append(row)
    return out


